#include <cuda_runtime.h>
#include <vector>
#include <cstring>
#include <string>
#include <chrono>
#include <filesystem>
#define main historical_main
#include "../clock-cuda/main.cu"
#undef main
#define CHECK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(11);}}while(0)
struct Case{int fixture,blocks;float*input,*output;clock_t*timer;uint32_t gold;};
uint32_t bits(float x){uint32_t w;memcpy(&w,&x,4);return w;}
int main(){static_assert(sizeof(clock_t)==8);std::vector<uint32_t>prefix(1042);FILE*f=fopen("/home/imo/HeCBench_julia/src/clock-julia/fixture.bin","rb");if(!f||fread(prefix.data(),4,prefix.size(),f)!=prefix.size())return 4;fclose(f);std::vector<Case>cases;for(int fixture=0;fixture<2;fixture++)for(int blocks:{1,32,8192}){Case c;c.fixture=fixture;c.blocks=blocks;CHECK(cudaMalloc(&c.input,512*4));CHECK(cudaMemcpy(c.input,prefix.data()+fixture*512,512*4,cudaMemcpyHostToDevice));float gold;memcpy(&gold,&prefix[fixture*512],4);for(int i=1;i<512;i++){float x;memcpy(&x,&prefix[fixture*512+i],4);if(x<gold)gold=x;}c.gold=bits(gold);CHECK(cudaMalloc(&c.output,(blocks+16)*4));CHECK(cudaMalloc(&c.timer,(2*blocks+16)*8));cases.push_back(c);}
auto launch=[](Case&c){timedReduction<<<c.blocks,256,2048>>>(c.input,c.output+8,c.timer+8);};for(auto&c:cases){launch(c);CHECK(cudaDeviceSynchronize());}
for(int trial=1;trial<=5;trial++){bool ok=true;double seconds=0;std::vector<uint32_t>art=prefix;std::vector<int64_t>raw;std::vector<double>path_times;for(auto&c:cases){std::vector<float>g(c.blocks+16,-12345.f);std::vector<clock_t>t(2*c.blocks+16,clock_t(-991827));CHECK(cudaMemcpy(c.output,g.data(),g.size()*4,cudaMemcpyHostToDevice));CHECK(cudaMemcpy(c.timer,t.data(),t.size()*8,cudaMemcpyHostToDevice));auto start=std::chrono::steady_clock::now();for(int rep=0;rep<100;rep++)launch(c);CHECK(cudaDeviceSynchronize());double dt=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/100;seconds+=dt;path_times.push_back(dt);CHECK(cudaMemcpy(g.data(),c.output,g.size()*4,cudaMemcpyDeviceToHost));CHECK(cudaMemcpy(t.data(),c.timer,t.size()*8,cudaMemcpyDeviceToHost));raw.insert(raw.end(),t.begin(),t.end());for(int i=0;i<c.blocks+16;i++){uint32_t w=bits(g[i]),want=i>=8&&i<c.blocks+8?c.gold:bits(-12345.f);ok&=w==want;art.push_back(w);}for(int i=0;i<16;i++){clock_t v=t[i<8?i:2*c.blocks+i];ok&=v==clock_t(-991827);art.push_back(uint32_t(v));}for(int i=0;i<c.blocks;i++){int64_t a=t[8+i],b=t[8+c.blocks+i];uint32_t delta=uint32_t(b)-uint32_t(a);bool format=(a==int64_t(uint32_t(a))||a==int64_t(int32_t(a)))&&(b==int64_t(uint32_t(b))||b==int64_t(int32_t(b)));bool pass=format&&delta>0&&delta<0x80000000u;ok&=pass;art.push_back(pass?1:0);}}
std::string dir=getenv("STUDY_OUTPUT_DIR")?getenv("STUDY_OUTPUT_DIR"):".";std::string path=dir+"/output_trial"+std::to_string(trial)+".bin";FILE*out=fopen(path.c_str(),"wb");fwrite(art.data(),4,art.size(),out);fclose(out);std::filesystem::path rawdir="/home/imo/HeCBench_julia/.porting-state/porting_logs/clock-julia-cuda/raw_timings";std::filesystem::create_directories(rawdir);std::string rawpath=(rawdir/(std::filesystem::path(dir).filename().string()+"_trial"+std::to_string(trial)+".bin")).string();out=fopen(rawpath.c_str(),"wb");fwrite(raw.data(),8,raw.size(),out);fclose(out);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"sum6_clocked_reduction_hostinclusive_batches_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":100,\"raw_timer_artifact\":{\"path\":\"%s\",\"dtype\":\"int64\",\"count\":%zu},\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%zu,\"byte_order\":\"little\"},\"path_times_seconds\":[",trial,seconds,ok?"true":"false",art.size()-prefix.size(),rawpath.c_str(),raw.size(),path.c_str(),art.size());for(int i=0;i<6;i++)printf("%s%.17g",i?",":"",path_times[i]);printf("]}\n");}
for(auto&c:cases){cudaFree(c.input);cudaFree(c.output);cudaFree(c.timer);}}
